mapper.select:
SELECT * FROM user_info
WHERE name LIKE 'DynRule%'
@{and, age = :age}
@{and, email = :email}
ORDER BY v <-> [0, 0] LIMIT 8 WITH (metric_type=L2)

SELECT * FROM user_info
WHERE name LIKE 'DynRule%'
AND (id < 0
@{or, age = :age}
@{or, email = :email}
)
ORDER BY v <-> [0, 0] LIMIT 8 WITH (metric_type=L2)

SELECT * FROM user_info
WHERE name LIKE 'DynRule%'
@{and, age >= :minAge}

    AND email = #{email}

ORDER BY v <-> [0, 0] LIMIT 8 WITH (metric_type=L2)

SELECT * FROM user_info
WHERE id > 0
@{and, name >= :name}
@{and, age >= :minAge}
@{and, age <= :maxAge}
ORDER BY v <-> [0, 0] LIMIT 8 WITH (metric_type=L2)
